// The facet aggregates (browse-scale D2): per-library counts of the
// synopsis group's genres/kind/status facts, computed at rebuild time by
// running the SAME naming resolver the About block serves — the projection
// arrives as a cmd-built closure (the package imports nothing internal,
// D2), so facets can never diverge from About by growing a second walk.
// A facet's inputs are only what the resolver already resolved WHOLE: the
// first effectively-enabled namespace carrying a description wins, and a
// winner without genres contributes nothing — no later namespace ever
// stitches in (reviewer Q5).

package browse

import (
	"encoding/json"
	"sort"
)

// The three facet keys, in served order.
const (
	facetKeyGenres = "genres"
	facetKeyKind   = "kind"
	facetKeyStatus = "status"
)

// Facet is one facet key's counted values for one library. Only keys at
// least one document's resolved About block carries are present — a key
// with no carrier anywhere is absent from the list (D2, honest absence).
type Facet struct {
	// Key is the facet dimension: "genres", "kind", or "status".
	Key string

	// Values are the distinct counted values, highest count first and
	// value-ascending within a tie — the deterministic serving order.
	Values []FacetValue
}

// FacetValue is one distinct value with its per-library count. A value is
// stored and served only at count >= 1 — count 0 omits the value (D2):
// the maps below only ever gain entries on an increment, so a zero can
// never be materialized, let alone served.
type FacetValue struct {
	Value string
	Count int
}

// buildFacets counts the per-library facet aggregates over the supplied
// series documents by running resolver — the SAME projection the About
// block serves (cmd wires naming.Namer.MetadataFor bound per library;
// OQ2) — on each document at rebuild time. Package-internal: the rebuild
// (task 2.3's service) is the only caller; only the Facet shape crosses
// to api. The returned map carries every supplied library id: a library
// whose documents resolve no synopsis carrier — a photo library has no
// series documents at all — maps to an empty non-nil list, the facet keys
// honestly absent. Documents that resolve nothing (unreadable, no chain,
// no carrier) contribute nothing; counting never errors.
func buildFacets(resolver func(libraryID string, raw json.RawMessage) map[string]any, docs map[string][]json.RawMessage) map[string][]Facet {
	out := make(map[string][]Facet, len(docs))
	for lib, raws := range docs {
		out[lib] = countLibraryFacets(resolver, lib, raws)
	}
	return out
}

// countLibraryFacets counts one library's facets: run the resolver per
// series document, take each resolved About block's ride-along facts, and
// count the usable values. Non-carrier documents and non-string scalars
// floor to nothing (the projection's tolerant posture); a nil resolver —
// the never-wired floor — counts nothing.
func countLibraryFacets(resolver func(libraryID string, raw json.RawMessage) map[string]any, libraryID string, raws []json.RawMessage) []Facet {
	genres := map[string]int{}
	kind := map[string]int{}
	status := map[string]int{}
	if resolver != nil {
		for _, raw := range raws {
			about, ok := resolver(libraryID, raw)["about"].(map[string]any)
			if !ok {
				continue // no synopsis carrier on THIS document
			}
			if arr, ok := about["genres"].([]any); ok {
				for _, e := range arr {
					if s, is := e.(string); is && s != "" {
						genres[s]++
					}
				}
			}
			countFacetScalar(about["kind"], kind)
			countFacetScalar(about["status"], status)
		}
	}
	facets := make([]Facet, 0, 3)
	for _, k := range []struct {
		key    string
		counts map[string]int
	}{
		{facetKeyGenres, genres},
		{facetKeyKind, kind},
		{facetKeyStatus, status},
	} {
		if vs := facetValues(k.counts); len(vs) > 0 {
			facets = append(facets, Facet{Key: k.key, Values: vs})
		}
	}
	return facets
}

// countFacetScalar counts one scalar facet value: a non-empty string
// counts, any other JSON shape floors to absent — the resolver passes
// members through verbatim, so the facet side owns the usable-value test.
func countFacetScalar(v any, counts map[string]int) {
	if s, ok := v.(string); ok && s != "" {
		counts[s]++
	}
}

// facetValues materializes one key's counted values in the serving order:
// count descending, value ascending within a tie. An empty count map
// yields nil — the key is omitted, never served as an empty value list.
func facetValues(counts map[string]int) []FacetValue {
	if len(counts) == 0 {
		return nil
	}
	vs := make([]FacetValue, 0, len(counts))
	for v, c := range counts {
		vs = append(vs, FacetValue{Value: v, Count: c})
	}
	sort.Slice(vs, func(i, j int) bool {
		if vs[i].Count != vs[j].Count {
			return vs[i].Count > vs[j].Count
		}
		return vs[i].Value < vs[j].Value
	})
	return vs
}
